import {CATALOG as OLD, LIMITS, QUESTIONS} from './catalog-v1.js';
export {LIMITS, QUESTIONS};
export const CATALOG_VERSION='2026.09-v2';
export const CATEGORIES=['Alle','Kampfschiffe','Unterstützung','Luftfahrzeuge','Unbemannte Systeme','Ausstattung','Marineinfanterie & Amphibik'];
const cost=values=>Object.fromEntries(['build','operation','personnel'].map((k,i)=>[k,values[i]*4]));
export const MODULES=Object.freeze({asw:{name:'U-Boot-Jagd'},surface:{name:'Seezielbekämpfung'},air:{name:'Luftverteidigung'},strike:{name:'Strike gegen Landziele',requires:['network']},recon:{name:'Vertiefte Aufklärung'}});
const prices={frigate:{asw:[6,2,0],surface:[4,1,0],air:[4,1,0],strike:[10,3,0]},corvette:{asw:[6,2,0],surface:[4,1,0],strike:[10,3,0]},helicopter:{asw:[1.5,1.25,0],surface:[2,1,0],recon:[1,.5,0]},plane:{asw:[2.5,1.5,0],surface:[3,1.5,0],recon:[2,1,0]},rotorDrone:{asw:[3,1,0],surface:[3,1,0],recon:[2,1,0]},fixedDrone:{surface:[4,1.5,0],recon:[2,1,0]}};
prices.cruiser=prices.frigate;
const hosts=['frigate','cruiser','supply','amphibiousCarrier'];
const edits={frigate:{name:'Fregatte',slots:2,description:'Grundbewaffnete Plattform für Präsenz, Sicherung und Stabilisierung. Zwei Ausstattungsplätze erlauben eigene Schwerpunkte.'},corvette:{slots:1},helicopter:{name:'Marinehubschrauber',unit:'1 Luftfahrzeug',cost:[1.5,.75,1],slots:2,hosts,optionalHost:true,description:'Transport, Suche, Rettung und einfache Beobachtung. Spezialisierte Sensoren und Wirkmittel werden zusätzlich gewählt.',strengths:['Transport und Rettung','Landgestützt oder eingeschifft'],limits:['Begrenzte Ausdauer','Spezialisierungen kosten zusätzlich']},marines:{optionalHost:true,description:'Landgestützte Marineinfanterie für Schutz- und Sicherungsaufgaben. Einschiffung ist optional und benötigt eigene expeditionäre Logistik.',limits:['Hoher Personalbedarf','Expeditionäre Logistik bei Einschiffung erforderlich']}};
const newCard=(id,name,values,shape,description,rules={})=>({id,name,category:'Luftfahrzeuge',cost:values,unit:'1 Luftfahrzeug',shape,description,strengths:['Grundfähigkeiten ohne Spezialisierung','Eigene Schwerpunkte wählbar'],limits:['Abstrakte Plattformfamilie','Keine beliebige Umrüstung realer Flugzeugmodelle'],...rules});
const additions=[newCard('cruiser','Großes Kampfschiff – Zerstörer/Kreuzer',[40,18,16],'cruiser','Mehr Raum für Sensoren, Wirkmittel und Führung erlaubt drei Schwerpunkte. Die Bezeichnungen sind keine weltweit einheitlichen Größenklassen; Strike ist keine exklusive Kreuzerfähigkeit.',{category:'Kampfschiffe',unit:'1 Schiff',slots:3,strengths:['Drei Spezialisierungsplätze','Größere Ausstattungsreserven'],limits:['Hohe Ressourcenbindung','Weniger Stückzahlen bei gleichem Budget']}),newCard('plane','Marineflächenflugzeug',[4,2,3],'plane','Transport, Suche und einfache Aufklärung. Keine Aufnahme von Personen aus dem Wasser.',{slots:2,requires:['airbase']}),newCard('rotorDrone','Drehflüglerdrohnen',[6,3,2],'rotorDrone','Aufklärung und Suchunterstützung. U-Boot-Jagd bedeutet Suche und Ortung, keine vollständige autonome Jagd. Bewaffnung ist eine abstrakte Spieloption.',{slots:1,unit:'1 Systempaket mit Betreuung',requires:['network'],hosts,optionalHost:true}),newCard('fixedDrone','Flächenflüglerdrohnen',[8,4,2],'fixedDrone','Landgestützte Aufklärung und Suchunterstützung. Kein Personentransport oder Aufnehmen von Menschen. Bewaffnung ist eine abstrakte Spieloption.',{slots:1,unit:'1 Systempaket mit Betreuung',requires:['network']})];
export const CATALOG=[...OLD.filter(c=>!['airdefense','patrol','transport','drone','effectors'].includes(c.id)).map(c=>({...c,cost:Object.values(c.cost),...edits[c.id]})),...additions].map(c=>({...c,category:c.category==='Amphibische Kräfte'?'Marineinfanterie & Amphibik':c.category,shape:['mine','tender','tanker','intelligence','dock','amphibiousCarrier','landing'].includes(c.id)?c.id:c.shape,cost:cost(c.cost),moduleCosts:Object.fromEntries(Object.entries(prices[c.id]||{}).map(([id,p])=>[id,cost(p)])),capacity:c.id==='frigate'||c.id==='cruiser'?{helicopter:2,rotorDrone:1}:c.id==='supply'?{helicopter:6,rotorDrone:1}:c.id==='amphibiousCarrier'?{helicopter:12,rotorDrone:1}:undefined}));
export const BY_ID=Object.assign(Object.create(null),Object.fromEntries(CATALOG.map(c=>[c.id,c])));
export const points=q=>q/4;
export const format=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(n);
